import os,sys,subprocess,json
R="/srv/projects/jellyfin-server"
d={"exists":os.path.isdir(R),"current_symlink":os.path.islink(R+"/current")}
if d["current_symlink"]:
 d["target"]=os.path.realpath(R+"/current")
 x=R+"/current/jellyfin"
 d["binary_exists"]=os.path.exists(x)
 d["binary_executable"]=os.access(x,os.X_OK)
 if d["binary_executable"]:
  try:
   p=subprocess.run([x,"--version"],capture_output=True,text=True,timeout=16)
   d["version"]={"returncode":p.returncode,"stdout":p.stdout[-1300:],"stderr":p.stderr[-1300:]}
  except Exception as e:d["version"]={"error_type":type(e).__name__,"message":str(e)[:200]}
d["top_entries"]=sorted(os.listdir(R))[:30] if d["exists"] else []
print(json.dumps(d,sort_keys=True))
